using System.IO.Compression;
using System.Text;

namespace Slh.Tms.Api.Services;

internal static class GeofenceSeedPayload
{
    // 53 Falcon geofences supplied by SLH on 17 August 2026. Stored compressed so
    // the production image can seed Azure SQL without relying on a mounted file.
    private const string GzipBase64 = "";

    public static string Json
    {
        get
        {
            var bytes = Convert.FromBase64String(GzipBase64);
            using var input = new MemoryStream(bytes);
            using var gzip = new GZipStream(input, CompressionMode.Decompress);
            using var output = new MemoryStream();
            gzip.CopyTo(output);
            return Encoding.UTF8.GetString(output.ToArray());
        }
    }
}
